// Shapes of the files in public/data, generated by data/scripts/06_build_app_data.mjs.
// Do not hand-edit public/data: change data/inputs/*.csv or the pipeline and rebuild.

export type RootDepth = 'shallow' | 'medium' | 'deep';

/** One crop from data/inputs/sowcast_crops.csv. Scores are 1 (low) to 5 (high). */
export interface Crop {
  id: string;
  name: string;
  family: string;
  season: string; // e.g. "wet season", "dry season", "perennial"
  role: string; // e.g. "main crop", "break crop", "cash crop", "green manure"
  water_need: number;
  nitrogen_fixing: boolean;
  root_depth: RootDepth;
  drought_tolerance: number;
  frost_tolerance: number;
  flood_tolerance: number;
  salinity_tolerance: number;
  sandy_soil_ok: number;
  temp_min_c: number;
  temp_max_c: number;
  season_days: number;
  seasonal_rain_need_mm: number;
  needs_flat_land: boolean;
  dry_season_crop: boolean;
  erosion_cover: number;
  organic_matter: number;
  market: number;
  forage_value: number;
  pest_notes: string;
  plain_description: string;
  /** Farming details from the team's crop table (rough regional averages). Scores 1 (low) to 5 (high). */
  yield_low: number | null;
  yield_high: number | null;
  yield_unit: string | null;
  n_fixed: string | null; // e.g. "~40-100 kg N/ha (rough)"; null for crops that don't fix nitrogen
  needs: { fertiliser: number | null; labour: number | null; seed_cost: number | null; pest_difficulty: number | null; storage_difficulty: number | null };
  relative_income: number | null;
  good_after: string[]; // crop ids
  avoid_after: string[]; // crop ids
  farmer_tip: string;
}

export interface RegionSummary {
  id: string;
  name: string; // e.g. "Central Dry Zone"
  place: string; // reference town, e.g. "Magway"
  country: string;
  lat: number;
  lon: number;
  tagline?: string;
  confidence: 'medium' | 'low'; // how well the team's draft region values are sourced
}

export interface MonthlyClimate {
  month: number; // 1-12
  tmax_c: number;
  tmin_c: number;
  precip_mm: number;
  et0_mm: number; // crop water demand (reference evapotranspiration)
  soil_moisture: number; // 0-1 soil wetness index (NASA POWER), not volumetric %
  ndvi: number | null; // 0-1 greenness; null until MODIS NDVI is fetched
  heat_days: number; // days ≥ 35 °C
  heavy_rain_days: number; // days ≥ 20 mm
  typically_bare: boolean | null; // null until NDVI is fetched
}

export interface AnnualClimate {
  year: number;
  heat_days: number;
  precip_mm: number;
  heavy_rain_days: number;
  max_dry_spell_days: number;
  water_balance_mm: number; // rain minus crop water demand
}

export interface TrendStat {
  per_decade: number | null;
  first_10y_mean: number | null;
  last_10y_mean: number | null;
  p: number | null; // Mann-Kendall p-value
}

export interface ClimateTrends {
  period: string; // e.g. "2001-2024"
  heat_days: TrendStat;
  precip_mm: TrendStat;
  heavy_rain_days: TrendStat;
  max_dry_spell_days: TrendStat;
  mean_water_balance_mm: number | null;
}

export interface SoilProfile {
  texture: string | null;
  organic_matter: string | null;
  drainage: string | null;
  water_holding: string | null;
  slope_pct: number | null;
  erosion_risk: string | null;
  sampled_km_from_town: number | null;
  source: string;
}

/** The team's draft region values (data/inputs/sowcast_regions.csv). Approximate, not measured. */
export interface RegionPriors {
  rain_mm: number;
  mean_temp_c: number;
  dry_months: number;
  soil_texture: string;
  drainage: string;
  slope_pct: number;
  flood_risk: number; // 0-3
  salinity_risk: number; // 0-3
  irrigation_access: number; // 0-3
  tree_crop_dominated: boolean;
  soil_degraded: boolean;
  common_crops: string[]; // crop ids
  evidence: string;
  confidence: 'medium' | 'low';
}

export interface PlainInsight {
  title: string;
  body: string;
  source: string;
  confidence: 'high' | 'medium' | 'experimental';
  badgeType?: 'warning' | 'opportunity' | 'neutral';
}

/** One month-by-month row of a plan's calendar. Each cell is a crop id (or "perennial_tree") or null for bare soil. */
export interface CalendarRow {
  label: string; // "Every year", "Year 1", "Trees", "Between rows"
  cells: (string | null)[]; // 12 entries, January first
}

export type PlanGoal = 'balanced' | 'soil_health' | 'market_income' | 'water_saving' | 'low_risk' | 'low_cost_labour';

/** A rotation: what farmers do now ('current') or one of the team recommender's top 3 for a goal. Scores 0-100. */
export interface RotationPlan {
  id: string; // stable across goals: the same sequence has the same id
  kind: 'current' | 'recommended';
  goal: PlanGoal | null;
  rank: number | null;
  name: string;
  tagline: string | null;
  plan_type: string; // e.g. "3-year rotation", "1-year double crop (wet season, then dry season)"
  /** Steps in order. A step can combine crops grown together ("perennial_tree+cover_legume"). Non-crop tokens: "fallow", "perennial_tree". */
  sequence: string[];
  goal_match: number | null;
  change_vs_current: number | null; // points better (+) or worse (-) than current practice on the goal's key score
  scores: { soil: number; market: number; water: number; resilience: number; low_cost: number; suitability: number } | null;
  why: string[];
  cautions: string[];
  evidence: string[];
  calendar: { rows: CalendarRow[]; approximate: boolean } | null;
  confidence: 'medium' | 'low';
  basis: string;
}

export interface RegionPlans {
  current: RotationPlan | null;
  by_goal: Record<PlanGoal, RotationPlan[]>;
}

/** One projected series: 2001-2024 history plus the 2035 projection with an 80% range. */
export interface ProjectedSeries {
  label: string;
  unit: string;
  per_decade: number;
  p: number;
  significance: 'likely' | 'possible' | 'none';
  model: 'theil_sen' | 'average';
  baseline: number; // 2001-2024 average
  recent_5y: number;
  bad_edge: 'low' | 'high';
  at_horizon: { year: number; mid: number; lo: number; hi: number };
  projection: { year: number; mid: number; lo: number; hi: number }[];
  history: { year: number; value: number }[];
}

export interface Consequence {
  kind: string;
  severity: 'high' | 'medium' | 'low';
  metric: string | null;
  headline: string;
  detail: string;
  action: string;
  crops: string[];
  significance: 'likely' | 'possible' | 'none' | 'variability' | 'projection';
}

export interface RegionOutlook {
  method: string;
  base_period: string;
  horizon: number;
  interval: number;
  series: Partial<Record<'precip_mm' | 'tmean_c' | 'heat_days' | 'heavy_rain_days' | 'max_dry_spell_days' | 'water_balance_mm' | 'dry_months', ProjectedSeries>>;
  crop_outlook: { crop: string; fit_now: number; fit_trend_2035: number; fit_bad_year_2035: number; water_now: number; water_bad_year: number }[];
  consequences: Consequence[];
}

export interface CropFitResult {
  crop: string; // crop id
  rank: number;
  fit: number; // 0-95 rule-based score
  fit_band: 'high' | 'medium' | 'low';
  trend: 'increasing' | 'flat' | 'declining' | 'unknown';
  limits: string[];
  why: string[];
  common_locally: boolean;
  parts: { climate: number; water: number; soil: number; risk: number; benefit: number };
  label: string | null; // "Very good fit" ...
  planting_window: string | null;
  harvest: string | null;
  sow_month: number | null;
  yield_outlook: string | null;
  rotation_tip: string | null;
}

export interface RegionDetail {
  region: { id: string; name: string; place: string; country: string; lat: number; lon: number };
  monthly: MonthlyClimate[];
  annual: AnnualClimate[];
  trends: ClimateTrends;
  /** 'suspect' = the weather series has a break around 2008 here; weather numbers are hidden. */
  data_quality: {
    weather: 'ok' | 'suspect';
    note: string | null;
    sources: { rain: string | null; temperature: string | null; greenness: string | null; power_replaced: boolean };
  };
  /** Region inputs used by the crop scores: the team's draft value vs the measured one, and which was used. */
  scoring_inputs: { input: string; draft: string | number | null; measured: string | number | null; used: 'draft' | 'measured'; source: string }[];
  soil: SoilProfile | null;
  priors: RegionPriors;
  insights: PlainInsight[];
  /** Rough wet-season months (team data) used for planting windows. */
  calendar: { wet_start: number | null; wet_end: number | null; confidence: string | null };
  rotation_relevance: string;
  plans: RegionPlans;
  /** Trends extended to 2035 and what they mean; null where the weather series is not reliable. */
  outlook: RegionOutlook | null;
  crop_fit: CropFitResult[];
  sources: string[];
}
